            if (wardenInstance.RiverqlHealthOption.IsSet && wardenInstance.RiverqlHealth == null)
                throw new ArgumentNullException(nameof(wardenInstance.RiverqlHealth), "Property is required for class WardenInstance.");

            writer.WriteString("fqdn", wardenInstance.Fqdn);

            writer.WriteString("slug", wardenInstance.Slug);

            var backendRawValue = WardenInstance.BackendEnumToJsonValue(wardenInstance.Backend);
            writer.WriteString("backend", backendRawValue);
            writer.WriteString("image", wardenInstance.Image);

            writer.WriteNumber("host_port", wardenInstance.HostPort);

            writer.WriteString("volume", wardenInstance.Volume);

            writer.WriteString("riverql_alias", wardenInstance.RiverqlAlias);

            writer.WriteString("created_by", wardenInstance.CreatedBy);

            writer.WriteString("created_at", wardenInstance.CreatedAt.ToString(CreatedAtFormat));

            var statusRawValue = WardenInstance.StatusEnumToJsonValue(wardenInstance.Status);
